def _rgb_to_hsv(rgbs):
    """Convert rgb to hsv"""
    r, g, b = rgbs
    max_ = max(r, g, b)
    min_ = min(r, g, b)
    h = 0
    s = 0
    v = max_
    if max_ != 0:
        s = (max_ - min_) / max_
    if s != 0:
        if r == max_:
            h = (g - b) / (max_ - min_)
        elif g == max_:
            h = 2 + (b - r) / (max_ - min_)
        else:
            h = 4 + (r - g) / (max_ - min_)
        h /= 6
    return h, s, v


def _hsv_to_rgb(hsv):
    """Convert hsv to rgb"""
    h, s, v = hsv
    i = int(h * 6)
    f = (h * 6) - i
    p = v * (1 - s)
    q = v * (1 - f * s)
    t = v * (1 - (1 - f) * s)
    i %= 6
    if i == 0:
        return v, t, p
    elif i == 1:
        return q, v, p
    elif i == 2:
        return p, v, t
    elif i == 3:
        return p, q, v
    elif i == 4:
        return t, p, v
    else:
        return v, p, q


