        if isinstance(arg, list):
            return set(arg)
        elif isinstance(arg, set):
            return arg
        elif isinstance(arg, tuple):
            return set(arg)
        elif isinstance(arg, dict):
            return {k: self.setify(v) for k, v in arg.items()}
        else:
            return set([arg])

