def decensor_url(url: str, site_url: str = DEFAULT_SITE) -> str:
    """Decensor a Danbooru URL.
    If the URL is already decensored, return it as is.
    If the URL is censored, return the decensored URL."""
    if url.startswith(site_url):
        return url
    else:
        return url.replace('https://', 'https://' + site_url)


def decensor_post(post: Post, site_url: str = DEFAULT_SITE) -> Post:
    """Decensor a Danbooru post.
    If the post is already decensored, return it as is.
    If the post is censored, return the decensored post."""
    if post.censored:
        post.file_url = decensor_url(post.file_url, site_url)
        post.preview_url = decensor_url(post.preview_url, site_url)
        post.censored = False
    return post


