class JSON(TypeDecorator):
    """
    Platform-independent JSON type.

    Uses PostgreSQL's JSON storage format on the server side, and JSON on the
    client side.
    """

    impl = TEXT

    def load_dialect_impl(self, dialect: Dialect) -> TypeEngine:
        """Load the dialect implementation."""
        if dialect.name == 'postgresql':
            return dialect.type_descriptor(JSONB)
        else:
            return dialect.type_descriptor(self.impl)

    def process_bind_param(self, value: Any, dialect: Dialect) -> Any:
        """Convert things on the way from Python to the database."""
        if value is None:
            return value
        elif isinstance(value, str):
            return value
        elif isinstance(value, (list, dict)):
            return json.dumps(value)
        else:
            raise TypeError(f'Invalid JSON: {value}')

    def process_result_value(self, value: Any, dialect: Dialect) -> Any:
        """Convert things on the way from the database to Python."""
        if value is None:
            return value
        elif isinstance(value, str):
            return json.loads(value)
        else:
            raise TypeError(f'Invalid JSON: {value}')


